sysevent_script_action.script:
function processCertificate(current) {
	var logger = new global.DiscoveryLogger(current.status, null);
	var daysBeforeExpiry = parseInt(gs.getProperty("glide.discovery.certs.days_before_expiration_to_create_renewal_task"));
	var now = new GlideDateTime();

	var cert = current.server_certificate;

	// EDX current é um registro de Discovered Certificate(sn_disco_certmgmt_certificate_history)
	if (!cert || !cert.sys_id || current.discovery_method != 'Remote') {
		log(logger, "EDX - Skipping certificate discovered on " + current.source + ':' + current.port);
		return current;
	}

	try {
		log(logger, "EDX - Processing Certificate " + cert.subject_common_name + ' - ' + cert.sys_id);

		var updatedFields = {
			u_ca_scope: null,
			renewal_tracking: 'none'
		};

		var updatedMetadata = {
			"certificate": cert.sys_id,
			"auto_renew_days_before_expiry": daysBeforeExpiry,
			"auto_renew_enabled": false,
			"auto_renewal_state": "ready"
		};

		if (cert.valid_to < now) {
			log(logger, "EDX - Expired Certificate " + cert.sys_id + ' - ' + cert.getDisplayValue());
		} else {
			if (cert.subject_common_name.endsWith('bnb.gov.br')) {
				updatedFields.u_ca_scope = 'external';
				updatedFields.renewal_tracking = 'priority1';
				updatedMetadata.auto_renew_enabled = true;
			} else {
				if (cert.subject_common_name.endsWith('intra.bnb') ||
					cert.subject_common_name.endsWith('dmz.bnb') ||
					cert.subject_common_name.endsWith('dreads.bnb')) {
					if (!(cert.is_self_signed || cert.is_ca) && cert.root_issuer != cert.sys_id) {
						updatedFields.u_ca_scope = 'internal';
						updatedFields.renewal_tracking = 'priority3';
						updatedMetadata.auto_renew_enabled = true;
					}
				}
			}
		}

		// Atualiza os campos no certificado (CA Scope e prioridade de renovação)
		log(logger, "EDX Updating Unique Certificate Table " + JSON.stringify(updatedFields));
		var uniqueCert = new global.GlideQuery("cmdb_ci_certificate")
			.where("sys_id", cert.sys_id)
			.updateMultiple(updatedFields);

		if (new global.GlideQuery("sn_disco_certmgmt_certificate_metadata")
			.where("certificate", cert.sys_id)
			.count() > 0) {
			new global.GlideQuery("sn_disco_certmgmt_certificate_metadata")
				.where("certificate", cert.sys_id)
				.updateMultiple(updatedMetadata);
			log(logger, "EDX Certificate Metadata updated: " + JSON.stringify(updatedMetadata));
		} else {
			if (updatedMetadata.auto_renew_enabled) {
				new global.GlideQuery("sn_disco_certmgmt_certificate_metadata")
					.insert(updatedMetadata);
				log(logger, "EDX Certificate Metadata created: " + JSON.stringify(updatedMetadata));
			}
		}
	} catch (ex) {
		log(logger, "EDX Failed to process Certificate - " + ex, "error");
	}
}

function log(logger, message, level) {
	if (level == "error") {
		logger.error(message);
		gs.error(message);
	} else {
		logger.info(message);
		gs.info(message);
	}
}

processCertificate(current);
